# Poison-message classifier + bounded DLQ router
NON_RETRYABLE = (ValueError, KeyError, UnicodeDecodeError)

def process_record(record, max_attempts: int = 3):
    attempt = int(record.headers.get("x-retry-count", 0))
    try:
        payload = parse_and_validate(record.value)
        handle_order_event(payload)
    except NON_RETRYABLE as exc:
        send_to_dlq(record, reason=str(exc)[:1024], permanent=True)
    except TransientError as exc:
        if attempt + 1 >= max_attempts:
            send_to_dlq(record, reason=f"retries_exhausted: {str(exc)[:900]}", permanent=False)
        else:
            publish_to_retry_topic(record, next_attempt=attempt + 1)
